/**
 * Query-time search plus the write-time index maintenance driven by the domain events.
 *
 * The query rules are ADR 0007. The query is parsed by `@/lib/search-query`, the same parser the dialog uses.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, consumeRateLimit
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { parseSearchQuery } from "@/lib/search-query";
import type { SearchSubjectKind } from "@/lib/search-query";
import { isLive } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { orgResource } from "./_support";
import type { SearchQueryInput } from "@/schemas/search";
import type { Comment } from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Project } from "@/types/project";

export type SearchHit = {
  kind: SearchSubjectKind;
  id: string;
  title: string;
  snippet: string;
  href: string;
};

/** Characters of surrounding context kept on either side of a match. */
const SNIPPET_RADIUS = 60;

/** Token bucket protecting the index from query bursts. */
const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index.
 *
 * Without `advanced_search` the query is free text and only issues are
 * searched, whatever kinds the caller asked for. With it, `kind:` tokens decide
 * the kinds (falling back to the caller's) and `project:` overrides the
 * caller's project. A query is never refused for its syntax.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const parsed = parseSearchQuery(input.q, advanced);
  const kinds: SearchSubjectKind[] = !advanced
    ? ["issue"]
    : parsed.kindTokens.length > 0
      ? [...parsed.kindTokens]
      : input.kinds;

  const page = await searchRepo.searchDocuments({
    ...input,
    q: parsed.text,
    kinds,
    projectId: parsed.projectId ?? input.projectId,
  });

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, parsed.text),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

/**
 * A comment belongs to the project of the issue it was posted on, so
 * `project:` scoping finds it (ADR 0007, rule 6).
 */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue?.projectId ?? null,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/**
 * Re-reads each row rather than trusting an event payload, so a partially
 * applied write is never indexed as if it had succeeded. A subject that no
 * longer exists, or is archived, is left out of the index (ADR 0007, rule 7).
 */
async function refreshIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue && isLive(issue)) await indexIssue(orgId, issue);
  else await removeFromIndex(orgId, "issue", issueId);
}

async function refreshComment(orgId: OrgId, commentId: CommentId): Promise<void> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (comment && isLive(comment)) await indexComment(orgId, comment);
  else await removeFromIndex(orgId, "comment", commentId);
}

async function refreshProject(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project && isLive(project)) await indexProject(orgId, project);
  else await removeFromIndex(orgId, "project", projectId);
}

async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  switch (subjectKind) {
    case "issue":
      return refreshIssue(orgId, subjectId as IssueId);
    case "comment":
      return refreshComment(orgId, subjectId as CommentId);
    case "project":
      return refreshProject(orgId, subjectId as ProjectId);
  }
}

/**
 * Keeps the index in step with writes.
 */
export function registerSearchListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await refreshIssue(payload.orgId, payload.issueId);
    }),
    subscribe("issue.updated", async (payload) => {
      await refreshIssue(payload.orgId, payload.issueId);
    }),
    subscribe("issue.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "issue", payload.issueId);
    }),
    subscribe("comment.created", async (payload) => {
      await refreshComment(payload.orgId, payload.commentId);
    }),
    subscribe("comment.updated", async (payload) => {
      await refreshComment(payload.orgId, payload.commentId);
    }),
    subscribe("comment.deleted", async (payload) => {
      await removeFromIndex(payload.orgId, "comment", payload.commentId);
    }),
    subscribe("project.created", async (payload) => {
      await refreshProject(payload.orgId, payload.projectId);
    }),
    subscribe("project.restored", async (payload) => {
      await refreshProject(payload.orgId, payload.projectId);
    }),
    subscribe("project.archived", async (payload) => {
      await removeFromIndex(payload.orgId, "project", payload.projectId);
    }),
    subscribe("search.reindex_requested", async (payload) => {
      await reindexSubject(payload.orgId, payload.subjectKind, payload.subjectId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

function hrefFor(kind: SearchSubjectKind, subjectId: string): string {
  switch (kind) {
    case "issue":
      return `/issues/${subjectId}`;
    case "comment":
      return `/comments/${subjectId}`;
    case "project":
      return `/projects/${subjectId}`;
  }
}

function snippetAround(content: string, query: string): string {
  const at = content.toLowerCase().indexOf(query.toLowerCase());
  if (at < 0) return content.slice(0, SNIPPET_RADIUS * 2);

  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(content.length, at + query.length + SNIPPET_RADIUS);
  return `${start > 0 ? "…" : ""}${content.slice(start, end)}${
    end < content.length ? "…" : ""
  }`;
}

